BEGIN;

-- tokens — 23 columns, primary key (contract_address)
CREATE TABLE IF NOT EXISTS public.tokens (
  contract_address             text NOT NULL,
  chain_id                     integer NOT NULL,
  creator_address              text NOT NULL,
  name                         text NOT NULL,
  symbol                       text NOT NULL,
  metadata_uri                 text NOT NULL,
  description                  text,
  logo_url                     text,
  buy_fee_bps                  integer NOT NULL,
  sell_fee_bps                 integer NOT NULL,
  graduation_threshold_usdc    numeric NOT NULL,
  real_usdc_reserves           numeric NOT NULL,
  token_reserves               numeric NOT NULL,
  virtual_usdc_reserves        numeric NOT NULL,
  virtual_token_reserves       numeric NOT NULL,
  graduated                    boolean NOT NULL,
  graduated_at                 timestamptz,
  -- DEFAULT below is INFERRED, not read from the API:
  -- nothing writes this column yet every live row reads 'unverified'; the frontend branches on it.
  verification_status          text DEFAULT 'unverified',
  created_at                   timestamptz,
  state                        text,
  creator_launch_purchased     numeric,
  creator_launch_bps           integer,
  lp_recipient                 text,
  PRIMARY KEY (contract_address)
