-- 003_list_page_columns.sql
-- ══════════════════════════════════════════════════════════════════════════

-- 003_list_page_columns.sql
--
-- Adds the columns the list page needs so that C2 (recent-buys ordering), C3 (collision
-- disclosure) and the 24h/7d volume windows arrive in ONE query instead of being derived
-- client-side or disabled outright.
--
-- Adds to tokens_with_volume:
--   last_buy_block, last_buy_at,
--   volume_24h_usdc, volume_7d_usdc, volume_all_usdc,
--   curve_token_supply, market_cap_usdc,
--   symbol_collision_count, name_collision_count
--
-- Adds two stored columns:
--   trades.block_time   -- see THE BUG below; this is the load-bearing part
--   tokens.curve_token_supply
--
-- Safe to run on a live database: additive on tables, and the view is recreated with
-- every column it had before plus the new ones. Re-runnable.
--
--
-- ═══ THE BUG THIS MIGRATION EXISTS AROUND ════════════════════════════════════
--
-- `trades.created_at` is the INDEXER'S INSERT TIME, not the block time. The indexer's
-- insert (src/index.js, handleTrade) does not supply it, so it defaults server-side to
-- now() at the moment the row is written.
--
-- That is not a theoretical distinction. Measured against live data on 30 August 2026,
-- comparing every trade row's created_at to the actual timestamp of its block:
--
--     block       created_at                block timestamp           drift
--     59446076    2026-08-29T14:54:35Z      2026-08-29T13:37:04Z      1.3 h
--     59458963    2026-08-30T22:21:12Z      2026-08-29T15:29:51Z     30.9 h
--     59459652    2026-08-30T22:21:15Z      2026-08-29T15:35:58Z     30.8 h
--
-- The 30-hour rows are trades the indexer ingested during a catch-up after being down.
-- They were stamped with the moment they were INGESTED. So at the time of writing, the
-- EXISTING volume_1h_usdc column reports 31-hour-old trades as one-hour volume, and the
-- list page renders that as live activity.
--
-- Building 24h and 7d windows on created_at would inherit exactly that failure, and it is
-- the specific failure mode that makes a window worse than no window: it looks live and
-- is not. Any backfill, any restart after downtime, any re-index re-stamps history as
-- "just now".
--
-- So the windows are computed on COALESCE(block_time, created_at):
--
--   * block_time is the truth and comes from the chain.
--   * created_at is the fallback for rows written before this migration, which keeps the
--     view working rather than blanking history.
--
-- ⚠ THE WINDOWS REMAIN APPROXIMATE UNTIL block_time IS POPULATED FOR EVERY ROW. The
--   indexer change and the backfill script ship alongside this file; until both have run,
--   the frontend must keep saying the windows are approximate. Do not remove that hover
--   text on the strength of this migration alone.
--
--
-- ═══ WHY THE VOLUME COLUMNS ARE COMPUTED, NOT STORED ═════════════════════════
--
-- Deliberate, and not an optimisation left on the table. A materialised aggregate that
-- goes stale during a busy launch is worse than no window at all, for the same reason as
-- above: it looks live and is not, and the moment it is most wrong is the moment it
-- matters most. Every volume figure here, and last_buy_block, is evaluated per query
-- against `trades`.
--
-- The cost is one grouped pass over trades per list query. At 10 trade rows that is free;
-- if it ever stops being free the answer is an index or a rollup table with an explicit
-- freshness column, NOT a silently stale number.

BEGIN;

-- ── 1. trades.block_time ─────────────────────────────────────────────────────
--
-- The block's own timestamp, from the chain. Nullable: NULL means "not yet backfilled",
-- which is distinct from any real time, and the view falls back rather than dropping the
-- row.
--
-- NOT a substitute for block_number in ORDERING. Arc produces sub-second blocks and
-- consecutive blocks can share a timestamp, so ordering is still by block_number
-- (CLAUDE.md §9.3). This column exists for TIME WINDOWS, which block numbers cannot
-- answer without a chain lookup.
ALTER TABLE public.trades
  ADD COLUMN IF NOT EXISTS block_time timestamptz;

-- The windows filter on it and the recent-buys ordering scans it per token.
CREATE INDEX IF NOT EXISTS trades_token_block_idx
  ON public.trades (token_address, block_number DESC);

CREATE INDEX IF NOT EXISTS trades_block_time_idx
  ON public.trades (block_time);

-- ── 2. tokens.curve_token_supply ───────────────────────────────────────────────────
--
-- Stored rather than hardcoded in the frontend, for the same reason creator_launch_bps
-- is (migration 002): the indexer reads it from the contract, so it cannot drift from
-- what the chain says the way a constant in a TypeScript file can.
--
-- ⚠ WHICH SUPPLY THIS IS, AND WHY IT IS THE CURVE SUPPLY. The contract exposes:
--
--     CURVE_TOKEN_SUPPLY   807,000,000e18   sold through the bonding curve
--     LP_TOKEN_RESERVE     193,000,000e18   held back to seed the pool at graduation
--     TOTAL_TOKEN_SUPPLY   1,000,000,000e18 the sum
--
-- This column holds CURVE_TOKEN_SUPPLY, and the name says so.
--
-- Market cap is price x CIRCULATING supply. During the curve phase the 193M LP reserve
-- is held by the factory and cannot be sold into the curve -- it is not circulating, and
-- pricing it as though it were overstates every market cap by 1000/807 = 1.24x. On a
-- product whose stated moat is verifiability, an inflated headline number is the wrong
-- thing to be wrong about.
--
-- ⚠ GRADUATED TOKENS ARE A DIFFERENT QUESTION AND THIS COLUMN DOES NOT ANSWER IT. After
-- graduation the 193M IS in the pool and IS tradeable, so the circulating figure and the
-- fully-diluted figure genuinely diverge -- and the card renders both MC and FDV. This
-- column is the curve-phase denominator; anything wanting a post-graduation circulating
-- supply must derive it separately rather than reusing this. Flagged, not solved.
ALTER TABLE public.tokens
  ADD COLUMN IF NOT EXISTS curve_token_supply numeric;

-- No backfill from SQL. NULL means "not yet observed by the indexer", which the view
-- renders as a NULL market cap rather than zero -- a zero market cap is a claim, NULL is
-- the absence of one. Rows settle on the next sync of that token.

COMMIT;

-- ═══ 3. The view ═════════════════════════════════════════════════════════════
--
-- Recreated in full. Every column it had before is preserved in its original position;
-- the new ones are appended.
--
-- ⚠ SECURITY INVOKER IS DELIBERATE AND MUST NOT BE "FIXED" TO DEFINER. See the long note
--   in 000_base_schema.sql. Under INVOKER the caller needs its own SELECT rights on
--   public.tokens and public.trades; without them the view returns ZERO ROWS AND NO
--   ERROR, the frontend shows an empty list, and nothing looks broken.
--
-- ⚠ DROP VIEW DISCARDS ITS GRANTS. The GRANT at the bottom of this file is not optional
--   boilerplate -- omitting it produces exactly the silent-empty-view failure above, and
--   the service-role key CANNOT detect it because service-role bypasses RLS entirely.
--   Verify with a real anon key after applying.

DROP VIEW IF EXISTS public.tokens_with_volume;

CREATE VIEW public.tokens_with_volume
WITH (security_invoker = true) AS
SELECT t.contract_address,
    t.chain_id,
    t.creator_address,
    t.name,
    t.symbol,
    t.metadata_uri,
    t.description,
    t.logo_url,
    t.buy_fee_bps,
    t.sell_fee_bps,
    t.graduation_threshold_usdc,
    t.real_usdc_reserves,
    t.token_reserves,
    t.virtual_usdc_reserves,
    t.virtual_token_reserves,
    t.graduated,
    t.graduated_at,
    t.verification_status,
    t.created_at,
    COALESCE(v.volume_1h_usdc, 0::numeric) AS volume_1h_usdc,
    t.state,
    t.creator_launch_purchased,
    t.creator_launch_bps,
    t.lp_recipient,

    -- ── 003: volume windows ──────────────────────────────────────────────────
    -- All four on the SAME SCALE as volume_1h_usdc: whole USDC, already divided by 1e6.
    -- Adding a raw-6dp-units column alongside these would be a unit drift waiting to
    -- happen, so every volume figure in this view is decimal USDC. Anything reading them
    -- must NOT divide again.
    COALESCE(v.volume_24h_usdc, 0::numeric) AS volume_24h_usdc,
    COALESCE(v.volume_7d_usdc,  0::numeric) AS volume_7d_usdc,
    COALESCE(v.volume_all_usdc, 0::numeric) AS volume_all_usdc,

    -- ── 003: recent buys (C2) ────────────────────────────────────────────────
    -- NULL, not 0, when a token has never been bought. "Never bought" is not "bought at
    -- block 0", and the frontend sorts nulls last on purpose rather than interleaving
    -- them. A 0 here would make a token nobody has touched sort as though it had a real
    -- buy, which is the thing recent-buys ordering exists to prevent.
    v.last_buy_block,
    v.last_buy_at,

    -- ── 003: is this token's window arithmetic EXACT? ─────────────────────────
    --
    -- TRUE when every trade behind the figures above carries a real block_time, so the
    -- windows mean what they say. FALSE when any of them is still falling back to
    -- created_at, which is ingest time and can be 30 hours adrift.
    --
    -- THE POINT OF THIS COLUMN IS THAT IT CLEARS ITSELF. The frontend shows its
    -- "approximate" note when this is false and stops when it is true, per token, with
    -- no flag to flip by hand. A caveat that needs a human to remove it is still on the
    -- page in October saying nothing.
    --
    -- A token with NO trades is exact by vacuous truth: there is nothing to be wrong
    -- about. bool_and over zero rows is NULL, hence the COALESCE.
    COALESCE(v.windows_exact, true) AS volume_windows_exact,

    -- ── 003: supply and market cap ───────────────────────────────────────────
    t.curve_token_supply,

    -- Computed per query from LIVE virtual reserves. NOT stored and NOT materialised:
    -- pinning it would let the pinned value drift from the reserves it claims to
    -- describe, which is the same failure as a stale volume window.
    --
    -- NULL rather than 0 when the inputs are unknown. A zero market cap is a claim about
    -- the token; NULL is the honest absence of one, and the frontend renders it as
    -- "unavailable".
    CASE
      WHEN t.curve_token_supply IS NULL OR t.virtual_token_reserves IS NULL
        OR t.virtual_token_reserves = 0 THEN NULL
      ELSE (t.virtual_usdc_reserves * t.curve_token_supply / t.virtual_token_reserves) / 1000000.0
    END AS market_cap_usdc,

    -- ── 003: collision disclosure (C3 / rule 2) ──────────────────────────────
    --
    -- Window functions, so the count arrives WITH the row and the frontend needs no
    -- second pass. The old client-side scan could only see the rows it had already
    -- fetched, which made it worse than nothing on a paginated list: a collision on page
    -- 4 would CLEAR tokens on page 1 that are in fact impersonated.
    --
    -- 1 means unique (the row counts itself). Anything above 1 is a collision, and BOTH
    -- sides of it carry the same count -- which of two identical tickers is "the real
    -- one" is not ours to assert.
    --
    -- SCOPE: every token, graduated included. The client-side version looked only at live
    -- tokens; that is widened here deliberately, because a graduated token is the most
    -- attractive thing to impersonate -- it succeeded, so people have heard of it.
    --
    -- Empty and NULL identifiers are forced to 1. Without this they all partition
    -- together and every unnamed token reports a collision with every other unnamed
    -- token, which is a false accusation rather than a missed one.
    CASE
      WHEN btrim(COALESCE(t.symbol, '')) = '' THEN 1
      ELSE count(*) OVER (PARTITION BY lower(btrim(t.symbol)))
    END AS symbol_collision_count,

    -- Names are normalised HARDER than symbols: case folded AND all whitespace removed,
    -- so "TxShape", "Txshape" and "Tx Shape" collapse to one key. A reader cannot tell
    -- those apart at a glance, and the whole point of the column is what a reader sees.
    --
    -- Name collision matters at least as much as symbol collision, and arguably more:
    -- symbol has a lock mechanism on chain (symbolLockDuration) which merely happens to
    -- be set to 0, whereas name has NO on-chain protection of any kind and never did.
    CASE
      WHEN btrim(COALESCE(t.name, '')) = '' THEN 1
      ELSE count(*) OVER (
        PARTITION BY regexp_replace(lower(btrim(t.name)), '\s+', '', 'g')
      )
    END AS name_collision_count

   FROM public.tokens t
     LEFT JOIN (
       -- ONE grouped pass over trades supplies every window and the recent-buy pointer.
       -- FILTER rather than four separate subqueries: same result, one scan.
       --
       -- The window predicate is COALESCE(block_time, created_at) -- block_time where the
       -- chain has told us, ingest time where it has not. See THE BUG at the top.
       SELECT tr.token_address,
              sum(tr.usdc_amount) FILTER (
                WHERE COALESCE(tr.block_time, tr.created_at) > now() - '01:00:00'::interval
              ) / 1000000.0 AS volume_1h_usdc,
              sum(tr.usdc_amount) FILTER (
                WHERE COALESCE(tr.block_time, tr.created_at) > now() - '24:00:00'::interval
              ) / 1000000.0 AS volume_24h_usdc,
              sum(tr.usdc_amount) FILTER (
                WHERE COALESCE(tr.block_time, tr.created_at) > now() - '7 days'::interval
              ) / 1000000.0 AS volume_7d_usdc,
              sum(tr.usdc_amount) / 1000000.0 AS volume_all_usdc,
              -- Ordering by BLOCK NUMBER, never by timestamp: Arc's sub-second blocks
              -- share timestamps, so max(block_time) can tie where max(block_number)
              -- cannot (CLAUDE.md §9.3).
              max(tr.block_number) FILTER (WHERE tr.is_buy) AS last_buy_block,
              max(COALESCE(tr.block_time, tr.created_at)) FILTER (WHERE tr.is_buy) AS last_buy_at,
              bool_and(tr.block_time IS NOT NULL) AS windows_exact
         FROM public.trades tr
        GROUP BY tr.token_address
     ) v ON v.token_address = t.contract_address;

-- ⚠ REQUIRED. DROP VIEW above discarded the grant; without this the view exists, returns
-- zero rows to anon, and raises no error. The tables' own RLS policies from
-- 000_base_schema.sql are unaffected by this migration and are not re-declared here.
GRANT SELECT ON public.tokens_with_volume TO anon, authenticated;

-- ═══ Verification — run with the ANON key, never the service key ═════════════
--
-- The service-role key bypasses RLS, so it returns rows whether or not the grant above
-- landed and CANNOT detect the failure this migration is most likely to cause.
--
--   node indexer/scripts/verify-anon-access.js
--
-- Expect a non-zero row count and every new column present. A row count of 0 with HTTP
-- 200 and no error is the signature of the missing grant, not of an empty database.
--
-- Sanity checks worth running once:
--
--   -- collisions: every count >= 1, and identical keys agree
--   SELECT name, symbol, symbol_collision_count, name_collision_count
--     FROM public.tokens_with_volume ORDER BY name_collision_count DESC;
--
--   -- market cap is derived from live reserves, not pinned
--   SELECT symbol, virtual_usdc_reserves, virtual_token_reserves, curve_token_supply,
--          market_cap_usdc
--     FROM public.tokens_with_volume WHERE curve_token_supply IS NOT NULL;
--
--   -- how much of the trade history still lacks a real block time
--   SELECT count(*) FILTER (WHERE block_time IS NULL) AS needs_backfill,
--          count(*) FILTER (WHERE block_time IS NOT NULL) AS exact,
--          count(*) AS total
--     FROM public.trades;
--
-- While `needs_backfill` is above zero the 1h/24h/7d windows are APPROXIMATE for any
-- token with unbackfilled trades, and the frontend must say so.
--
-- ═══ Rollback ════════════════════════════════════════════════════════════════
--
--   BEGIN;
--   DROP INDEX IF EXISTS trades_token_block_idx;
--   DROP INDEX IF EXISTS trades_block_time_idx;
--   ALTER TABLE public.trades DROP COLUMN IF EXISTS block_time;
--   ALTER TABLE public.tokens DROP COLUMN IF EXISTS curve_token_supply;
--   COMMIT;
--
-- Then restore the view from 000_base_schema.sql and re-run its GRANT. Dropping the
-- columns without restoring the view leaves a view referencing columns that no longer
-- exist; Postgres will refuse the DROP COLUMN until the view is dropped first.

-- ── applied-state stamp ──────────────────────────────────────────────────────
--
-- ⚠ GUARDED with to_regclass, so this file can be applied in ANY order relative to
-- 005 (which creates the table). An unguarded INSERT would make every migration below
-- 005 fail on a database that has not reached 005 yet -- turning a tracking convenience
-- into a hard ordering dependency, which is the opposite of what it is for.
DO $$
BEGIN
  IF to_regclass('public.schema_migrations') IS NOT NULL THEN
    INSERT INTO public.schema_migrations (version) VALUES ('003')
    ON CONFLICT (version) DO NOTHING;
  END IF;
END $$;


-- ══════════════════════════════════════════════════════════════════════════
-- 004_trade_reserves_and_ohlc.sql
-- ══════════════════════════════════════════════════════════════════════════

-- 004_trade_reserves_and_ohlc.sql
--
-- Adds the post-trade curve state to `trades`, and a candle view built on it.
--
--   trades.virtual_usdc_reserves    numeric
--   trades.virtual_token_reserves   numeric
--   view  token_candles_1m
--
-- Safe to run on a live database: additive, nothing dropped or rewritten, re-runnable.
-- Does NOT touch tokens_with_volume, so 003's grants are unaffected.
--
--
-- ═══ WHY THE CHART CANNOT USE EXECUTION PRICE ════════════════════════════════
--
-- This is the whole reason the migration exists, and it was found by deriving price from
-- the trade rows we already had:
--
--     block       side   usdc      tokens    price
--     59446076    BUY    2.0000    153147    $1.306e-5
--     59446082    SELL   0.1881     76573    $2.457e-6
--     59446156    BUY    2.0000    153147    $1.306e-5
--     59446162    SELL   0.1881     76573    $2.457e-6
--
-- A 5.3x sawtooth between ADJACENT trades at the SAME reserve level. That is not the
-- market -- it is the snipe tax and the fees. `usdc_amount / token_amount` is the
-- effective EXECUTION price including tax, so charting it draws the fee schedule rather
-- than the price.
--
-- And it is worst exactly where it matters most: the snipe tax opens at 9800 bps, so
-- every new token's chart would begin with an enormous spike that means nothing. Nobody
-- looking at it would know why.
--
-- ⚠ THE CHART PLOTS CURVE MID-PRICE, DERIVED FROM RESERVES. Never usdc/token.
--
--     mid_price = virtual_usdc_reserves / virtual_token_reserves
--
-- That is the price the curve itself is at, tax-free and fee-free, which is what a
-- candle is supposed to show.
--
--
-- ═══ WHY THE RESERVES MUST BE STORED PER TRADE ═══════════════════════════════
--
-- `tokens` holds only the CURRENT reserves. Once a second trade lands, the state at the
-- first is gone forever -- it cannot be recovered from the row, and re-deriving it would
-- mean replaying every trade through the curve formula, which is CLAUDE.md §1.3's
-- explicit "never re-derive the curve math".
--
-- The indexer already reads `curves(token)` after every trade (updateReservesFromChain).
-- These two columns are written from THAT read. No extra RPC call.
--
--
-- ═══ WHY EMPTY BUCKETS ARE NOT A GAP TO FILL ═════════════════════════════════
--
-- On a bonding curve, price is a pure function of reserves, and reserves change ONLY
-- when someone trades. So between trades the price is not unknown or interpolated -- it
-- is EXACTLY constant.
--
-- A minute with no trades is therefore a real candle with O=H=L=C at the last price, and
-- that is a true statement rather than a smoothing artefact. The forward-fill below is
-- arithmetic, not estimation. (Confirmed against pump.fun, whose own API exposes the same
-- virtual/real reserve pair: they are not doing anything clever either, because there is
-- nothing clever to do.)

BEGIN;

-- ── 1. post-trade curve state ────────────────────────────────────────────────
--
-- Nullable: NULL means "recorded before this migration", and the candle view skips those
-- rows rather than inventing a price for them. numeric, not bigint -- virtual token
-- reserves are ~1e27 and overflow bigint.
ALTER TABLE public.trades
  ADD COLUMN IF NOT EXISTS virtual_usdc_reserves  numeric;

ALTER TABLE public.trades
  ADD COLUMN IF NOT EXISTS virtual_token_reserves numeric;

-- The candle view groups by token and time bucket.
CREATE INDEX IF NOT EXISTS trades_token_blocktime_idx
  ON public.trades (token_address, block_time);

COMMIT;

-- ═══ 2. The candle view ══════════════════════════════════════════════════════
--
-- One-minute buckets. Coarser intervals are derived by re-bucketing this in the query
-- rather than by adding more views, so there is one definition of price.
--
-- ⚠ BUCKETS ON block_time, NEVER created_at. created_at is the indexer's INSERT time and
--   carried up to 30.9 HOURS of drift on real rows (see 003). Bucketing on it would put
--   the ingest schedule on the chart's x-axis instead of the chain's.
--
-- ⚠ ORDERING WITHIN A BUCKET IS BY block_number, NEVER block_time. Arc produces
--   sub-second blocks and consecutive blocks can share a timestamp (CLAUDE.md §9.3), so
--   first_value/last_value ordered by time would pick an arbitrary row among ties.
--   Ordering by (block_number, id) is total.

DROP VIEW IF EXISTS public.token_candles_1m;

CREATE VIEW public.token_candles_1m
WITH (security_invoker = true) AS
WITH priced AS (
  SELECT
      tr.token_address,
      date_trunc('minute', tr.block_time) AS bucket,
      tr.block_number,
      tr.id,
      -- Curve mid-price in USDC per whole token. USDC is 6dp, launched tokens are 18dp,
      -- so the 1e12 rescales the ratio into a per-token price.
      (tr.virtual_usdc_reserves / tr.virtual_token_reserves) * 1000000000000.0 AS mid_price,
      tr.usdc_amount / 1000000.0 AS usdc_volume
    FROM public.trades tr
   WHERE tr.block_time IS NOT NULL
     AND tr.virtual_token_reserves IS NOT NULL
     AND tr.virtual_token_reserves > 0
     AND tr.virtual_usdc_reserves IS NOT NULL
)
SELECT
    token_address,
    bucket,
    (array_agg(mid_price ORDER BY block_number ASC,  id ASC))[1] AS open,
    max(mid_price)                                               AS high,
    min(mid_price)                                               AS low,
    (array_agg(mid_price ORDER BY block_number DESC, id DESC))[1] AS close,
    sum(usdc_volume)                                             AS volume_usdc,
    count(*)                                                     AS trade_count
  FROM priced
 GROUP BY token_address, bucket;

-- ⚠ REQUIRED. A view created without a grant returns ZERO ROWS to anon and raises NO
-- ERROR, and the service-role key cannot detect it because service-role bypasses RLS.
-- Same trap as 003; see the long note in 000_base_schema.sql.
GRANT SELECT ON public.token_candles_1m TO anon, authenticated;

-- ═══ Verification, with the ANON key ═════════════════════════════════════════
--
--   SELECT token_address, bucket, open, high, low, close, trade_count
--     FROM public.token_candles_1m ORDER BY bucket;
--
-- Expect one row per token per minute that contained a trade. A NON-ZERO row count is
-- the check that matters -- zero rows with HTTP 200 means the grant did not land.
--
-- Sanity: open/high/low/close for a single-trade bucket must all be EQUAL. If they
-- differ, the price is being taken from usdc_amount/token_amount somewhere rather than
-- from the reserves, and the sawtooth is back.
--
--   SELECT count(*) FILTER (WHERE virtual_token_reserves IS NULL) AS pre_004,
--          count(*) FILTER (WHERE virtual_token_reserves IS NOT NULL) AS usable
--     FROM public.trades;
--
-- Rows written before 004 have no reserves and are invisible to the chart. They are not
-- backfillable: the curve state at that block is not recoverable from the row, and
-- re-deriving it would mean re-implementing the curve math (CLAUDE.md §1.3). The chart
-- simply starts from the first trade indexed after this migration.
--
-- ═══ FORWARD-FILL BELONGS IN THE QUERY, NOT HERE ═════════════════════════════
--
-- This view emits only buckets that CONTAIN a trade. A continuous series is produced by
-- carrying `close` forward across empty buckets, which the client does when building the
-- series (or a generate_series LEFT JOIN can do server-side if it ever needs to).
--
-- It is deliberately not baked in: a view that emitted a row per minute forever would
-- generate unbounded rows for a token nobody has traded since launch, and the emptiness
-- is information the caller may want to see.
--
-- ═══ Rollback ════════════════════════════════════════════════════════════════
--
--   BEGIN;
--   DROP VIEW IF EXISTS public.token_candles_1m;
--   DROP INDEX IF EXISTS public.trades_token_blocktime_idx;
--   ALTER TABLE public.trades DROP COLUMN IF EXISTS virtual_usdc_reserves;
--   ALTER TABLE public.trades DROP COLUMN IF EXISTS virtual_token_reserves;
--   COMMIT;
--
-- The indexer writes both columns. Dropping them without reverting src/index.js makes
-- every subsequent trade insert fail on the missing column rather than degrade.

-- ── applied-state stamp ──────────────────────────────────────────────────────
--
-- ⚠ GUARDED with to_regclass, so this file can be applied in ANY order relative to
-- 005 (which creates the table). An unguarded INSERT would make every migration below
-- 005 fail on a database that has not reached 005 yet -- turning a tracking convenience
-- into a hard ordering dependency, which is the opposite of what it is for.
DO $$
BEGIN
  IF to_regclass('public.schema_migrations') IS NOT NULL THEN
    INSERT INTO public.schema_migrations (version) VALUES ('004')
    ON CONFLICT (version) DO NOTHING;
  END IF;
END $$;


-- ══════════════════════════════════════════════════════════════════════════
-- 005_schema_migrations.sql
-- ══════════════════════════════════════════════════════════════════════════

-- 005_schema_migrations.sql
--
-- Applied-state tracking. Until now there was NONE: no table, no log, nothing. A fresh
-- environment had no way to answer "which migrations has this database had?" except by
-- inspecting columns one at a time and inferring — which is exactly how APPLY-ALL.sql came
-- to be missing twelve objects without anyone noticing.
--
-- ── ⚠ THE SECURITY POSTURE IS COPIED FROM indexer_state, DELIBERATELY ─────────
--
-- This repo protects its non-public tables with TWO INDEPENDENT BARRIERS, and the
-- distinction matters because they fail differently:
--
--   1. NO GRANT. anon has no privilege, so a write is refused with `42501 permission
--      denied` BEFORE RLS is ever consulted.
--   2. RLS enabled with NO policy, so even a granted role matches no rows.
--
-- CLAUDE.md records that these are separate, that a `204` (grant held, RLS matched
-- nothing) and a `401`/`42501` (refused outright) are different answers, and that the
-- REVOKE was the fix when anon turned out to hold UPDATE/DELETE grants Supabase had
-- granted by default. `GRANT SELECT` ADDS to whatever is already there — it does not
-- replace it — which is how those grants survived unnoticed in the first place.
--
-- So this table is created the way `indexer_state` is created in 000, and for the same
-- reason: it is operational metadata, not public data. It is NOT added to the anon SELECT
-- grant. Nothing in the frontend reads it, and nothing should — a schema version is a
-- deployment detail, and publishing one tells an attacker exactly which migrations a
-- database is missing.
--
-- ⚠ Writes are expected to come from the SQL editor (or any superuser applying DDL), never
-- through PostgREST. That is not a limitation to work around: the service-role key cannot
-- run DDL at all, so anything applying a migration already has SQL access, and giving
-- PostgREST a write path here would be a new hole for no gain.

BEGIN;

CREATE TABLE IF NOT EXISTS public.schema_migrations (
  -- The numeric prefix of the migration file: '000', '001', ... Text rather than integer
  -- so the leading zero survives and so a future '004a' hotfix has somewhere to go.
  version     text        NOT NULL,
  applied_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (version)
);

COMMENT ON TABLE public.schema_migrations IS
  'Which numbered migrations have been applied. Operational metadata: no anon grant, RLS on with no policy. See 005_schema_migrations.sql.';

-- Barrier 1: no privilege for the public roles.
REVOKE ALL ON public.schema_migrations FROM anon, authenticated;

-- Barrier 2: RLS on, and deliberately NO policy. Even if a grant were added by accident
-- (Supabase's defaults have done exactly that before), there is no policy to match.
ALTER TABLE public.schema_migrations ENABLE ROW LEVEL SECURITY;

-- Backfill what this database already has. Every migration below 005 is additive and
-- idempotent, so recording them here asserts only what the objects themselves show.
--
-- ⚠ Run this ONLY on a database that genuinely has them. On a fresh database this whole
-- file runs as part of APPLY-ALL, where the preceding migrations have just executed.
INSERT INTO public.schema_migrations (version) VALUES
  ('000'), ('001'), ('002'), ('003'), ('004'), ('005')
ON CONFLICT (version) DO NOTHING;

COMMIT;


-- ══════════════════════════════════════════════════════════════════════════
-- 006_candle_open_from_previous.sql
-- ══════════════════════════════════════════════════════════════════════════

-- 006_candle_open_from_previous.sql
--
-- Give every trade a candle with a BODY, by taking its open from the previous trade's
-- stored reserves.
--
-- ── THE BUG ───────────────────────────────────────────────────────────────────
--
-- `trades.virtual_*_reserves` are the POST-trade curve state. The 004 view priced every
-- trade at that one number and then aggregated per bucket:
--
--   open  = first mid_price in the bucket
--   close = last  mid_price in the bucket
--   high  = max, low = min
--
-- For a bucket holding ONE trade -- which is almost every bucket on a bonding curve --
-- open = high = low = close. The candle has no body. It renders as a flat dash, and a
-- chart of flat dashes is a line drawn expensively.
--
-- That is not what a trade is. A trade SWEEPS a price range: it starts at the curve price
-- before it executed and ends at the price after. pump.fun's candles have bodies for
-- exactly this reason, not because their buckets are busier than ours.
--
-- ── THE FIX, AND WHAT IT DOES NOT DO ──────────────────────────────────────────
--
-- The pre-trade price is already stored -- it is the PREVIOUS trade's post-trade price.
-- So `lag()` over (token, block_number, id) recovers it with no new columns and no new
-- indexer work.
--
-- ⚠ NO CURVE MATH IS RE-DERIVED HERE, and that is deliberate. CLAUDE.md §1.3 is explicit
-- that the curve has been re-derived incorrectly more than once, including a frontend
-- version that overstated output by 98.96x at t=0. This view reads two adjacent stored
-- rows and subtracts nothing. If the reserves are right, the candle is right.
--
-- ⚠ ORDERING IS block_number THEN id, NEVER block_time. Arc's sub-second blocks share
-- timestamps, so ordering by time would shuffle trades within a block and hand a candle
-- the wrong neighbour. Bucketing still uses block_time -- that is what a minute IS -- but
-- sequence never does.
--
-- ⚠ THE FIRST TRADE OF A TOKEN HAS NO PREDECESSOR. `lag()` yields NULL and it is
-- COALESCEd back to its own price, so that one candle is still a dash. That is honest: no
-- pre-trade price was ever stored for it, and the alternative -- computing the launch
-- price from the curve constants -- is precisely the re-derivation the rule above forbids.
-- It affects exactly one candle per token, at the far left of the chart.

BEGIN;

DROP VIEW IF EXISTS public.token_candles_1m;

CREATE VIEW public.token_candles_1m
WITH (security_invoker = true) AS
WITH priced AS (
  SELECT
      tr.token_address,
      date_trunc('minute', tr.block_time) AS bucket,
      tr.block_number,
      tr.id,
      -- Curve mid-price in USDC per whole token, AFTER this trade. USDC is 6dp, launched
      -- tokens are 18dp, so the 1e12 rescales the ratio into a per-token price.
      (tr.virtual_usdc_reserves / tr.virtual_token_reserves) * 1000000000000.0 AS close_price,
      tr.usdc_amount / 1000000.0 AS usdc_volume
    FROM public.trades tr
   WHERE tr.block_time IS NOT NULL
     AND tr.virtual_token_reserves IS NOT NULL
     AND tr.virtual_token_reserves > 0
     AND tr.virtual_usdc_reserves IS NOT NULL
),
swept AS (
  SELECT
      p.*,
      -- The price this trade STARTED from: the previous trade's post-trade price.
      -- COALESCE to its own close for the first trade of a token (see the header).
      COALESCE(
        lag(p.close_price) OVER (
          PARTITION BY p.token_address
          ORDER BY p.block_number ASC, p.id ASC
        ),
        p.close_price
      ) AS open_price
    FROM priced p
)
SELECT
    token_address,
    bucket,
    -- The bucket opens where its FIRST trade started sweeping, not where that trade ended.
    (array_agg(open_price  ORDER BY block_number ASC,  id ASC))[1]  AS open,
    -- ⚠ High and low span BOTH ends of every sweep in the bucket. Taking max/min of the
    -- close alone would clip the wick on the side the price came from, which is how a
    -- candle ends up smaller than the move it represents.
    GREATEST(max(open_price), max(close_price))                     AS high,
    LEAST(min(open_price), min(close_price))                        AS low,
    (array_agg(close_price ORDER BY block_number DESC, id DESC))[1] AS close,
    sum(usdc_volume)                                                AS volume_usdc,
    count(*)                                                        AS trade_count
  FROM swept
 GROUP BY token_address, bucket;

-- ⚠ RE-GRANT. DROP VIEW discards the grant, and this view is SECURITY INVOKER: without
-- it the anon role gets ZERO ROWS AND NO ERROR, the chart renders empty, and an empty
-- chart is also exactly what a token with no trades legitimately looks like. This is the
-- single most repeated trap in this schema.
GRANT SELECT ON public.token_candles_1m TO anon, authenticated;

-- ── applied-state stamp ──────────────────────────────────────────────────────
--
-- Guarded with to_regclass so this file can be applied in any order relative to 005.
DO $$
BEGIN
  IF to_regclass('public.schema_migrations') IS NOT NULL THEN
    INSERT INTO public.schema_migrations (version) VALUES ('006')
    ON CONFLICT (version) DO NOTHING;
  END IF;
END $$;

COMMIT;


-- ══════════════════════════════════════════════════════════════════════════
-- 007_revoke_view_grants.sql
-- ══════════════════════════════════════════════════════════════════════════

-- 007_revoke_view_grants.sql
--
-- Strip Supabase's default ACL from the two views, leaving SELECT only.
--
-- ── WHAT WAS FOUND ────────────────────────────────────────────────────────────
--
-- Supabase grants INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES and TRIGGER to `anon` and
-- `authenticated` on every new object in the public schema. Migration 000 revokes those on
-- the BASE TABLES, so a write there fails at the grant layer independently of RLS -- two
-- independent barriers, which CLAUDE.md records as settled.
--
-- The views were created afterwards and never got that treatment. Inspected on the live
-- database, `token_candles_1m` and `tokens_with_volume` each carried all six.
--
-- ⚠ NOT CURRENTLY EXPLOITABLE, AND THAT IS NOT THE POINT. Both views use GROUP BY and
-- window functions, so neither is auto-updatable and Postgres rejects writes regardless of
-- the grant. The principle is that the grant layer is supposed to be the first barrier,
-- and the next view added might be a simple one that IS auto-updatable -- at which point
-- the default ACL becomes a write path nobody added deliberately.
--
-- ── WHY THIS FILE EXISTS WHEN THE LIVE DATABASE IS ALREADY FIXED ──────────────
--
-- It was fixed by hand in the dashboard. A dashboard fix does not reproduce: a fresh
-- production database bootstrapped on 16 September gets the permissive defaults again,
-- and nothing would say so.
--
-- ⚠ REVOKE ALL THEN GRANT SELECT, not individual REVOKEs. An enumerated list can only
-- revoke the privileges known when it was written; `ALL` also removes whatever Supabase
-- adds to its defaults later.
--
-- ⚠ THE OVER-REVOKE FAILURE IS SILENT AND LOOKS LIKE SUCCESS. Dropping SELECT too would
-- make both views return ZERO ROWS WITH NO ERROR -- and an empty token list is also
-- exactly what launch day legitimately looks like. That is why the GRANT is not optional
-- and why VERIFY-SCHEMA.sql asserts SELECT is present as well as asserting the others are
-- absent. Verify with the ANON key; the service key bypasses RLS and cannot see it.

BEGIN;

REVOKE ALL ON public.token_candles_1m FROM anon, authenticated;
REVOKE ALL ON public.tokens_with_volume FROM anon, authenticated;

GRANT SELECT ON public.token_candles_1m TO anon, authenticated;
GRANT SELECT ON public.tokens_with_volume TO anon, authenticated;

-- ── applied-state stamp ──────────────────────────────────────────────────────
--
-- Guarded with to_regclass so this file can be applied in any order relative to 005,
-- matching 005 and 006.
DO $$
BEGIN
  IF to_regclass('public.schema_migrations') IS NOT NULL THEN
    INSERT INTO public.schema_migrations (version) VALUES ('007')
    ON CONFLICT (version) DO NOTHING;
  END IF;
END $$;

COMMIT;


-- ══════════════════════════════════════════════════════════════════════════
-- applied-state record
-- ══════════════════════════════════════════════════════════════════════════
--
-- Each numbered migration also stamps its own row (see the tail of each file). This block
-- is the belt-and-braces for a bundle run: it records every version this file contains.
INSERT INTO public.schema_migrations (version) VALUES
  ('000'),
  ('001'),
  ('002'),
  ('003'),
  ('004'),
  ('005'),
  ('006'),
  ('007')
ON CONFLICT (version) DO NOTHING;
